def balanced(s):
    in_string = None
    i = 0
    stack = []
    n = len(s)
    while i < n:
        ch = s[i]
        if in_string is None:
            if ch in ('"', "'"):
                in_string = ch
                i += 1
                continue
            if ch in '([{':
                stack.append(ch)
            elif ch in ')]}':
                if not stack:
                    return False
                top = stack.pop()
                if (top == '(' and ch != ')') or (top == '[' and ch != ']') or (top == '{' and ch != '}'):
                    return False
            i += 1
        else:
            if ch == '\\':
                i += 2
                continue
            if ch == in_string:
                in_string = None
                i += 1
                continue
            i += 1
    if in_string is not None:
        return False
    return len(stack) == 0

